
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_hyb_tau_hcth_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_hyb_tau_hcth", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.010765169273858e-01, -1.004582830173084e-01, -9.958712553645784e-02, -9.837314518253826e-02, -9.670880069528424e-02, -9.447116892952007e-02, -9.147519161440920e-02, -8.710700570584659e-02, -7.865933539907917e-02, -5.814142429935305e-02, -2.891891121506981e-02, -5.321176487795044e-02, -4.929582930566705e-02, -4.418115259407084e-02, -2.879988440911269e-02, 6.262955573153468e-03, 1.831056164420817e-02, 4.339382179149779e-03, -4.093555982422029e-04, -1.622507757456545e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


